import type { PackageMetadataFields } from "@uipath/common";
import type { RulesConfigFileType } from "@uipath/solution-packager/node";
/**
 * Options for the PackCommandService
 */
export interface PackCommandOptions extends PackageMetadataFields {
    /**
     * Output directory where the packed solution will be saved.
     * Required for real packs; ignored in dry-run mode (a temp directory is
     * allocated and discarded instead).
     */
    output?: string;
    /** Package name (default: solution folder name) */
    name?: string;
    /** Package version (default: 1.0.0) */
    version?: string;
    /** Solution classification — `standard` or `vertical`. Absent means standard. */
    solutionType?: string;
    /** Minimum minutes before token expiration to trigger a refresh (default: 10) */
    loginValidity?: number;
    /**
     * Run the full pack pipeline against a temporary directory and discard the
     * produced artefacts. Surfaces the strict deploy-time validator without
     * committing to a package build.
     */
    dryRun?: boolean;
    /**
     * Path to a NuGet sources configuration file. Forwarded to the packager for
     * every project in the solution. When set, it overrides the feeds resolved
     * from the authenticated session; a JSON feeds file is merged with the
     * tenant's Orchestrator feeds, a NuGet.config XML is used as-is.
     */
    nugetSourcesConfigPath?: string;
    /**
     * Resolve dependencies only from the feeds this command supplies — the
     * session's Orchestrator feeds (or `feedFolder`) and
     * `nugetSourcesConfigPath`. Drops the WorkflowCompiler's built-in feeds
     * (nuget.org, UiPath-Official, Connect, internal) and its predefined local
     * package folders.
     */
    excludeConfiguredSources?: boolean;
    /**
     * Orchestrator folder whose library feed resolves this solution's project
     * dependencies, instead of every accessible tenant library feed. Accepts a
     * folder name or a fully qualified path.
     */
    feedFolder?: string;
    /**
     * Path to a .pfx certificate. When set, each packed project .nupkg is
     * signed with `dotnet nuget sign` before the solution .zip is assembled.
     */
    signingCertificatePath?: string;
    /** Password for the signing certificate. */
    signingCertificatePassword?: string;
    /** RFC 3161 timestamp server URL for the signature. */
    signingTimestampServer?: string;
    /**
     * Skip the workflow analyzer for every project in the solution. The
     * WorkflowCompiler still compiles and validates; only the analyzer rules
     * are not run.
     */
    skipAnalyze?: boolean;
    /**
     * Path to a local governance policy file to analyze against. Selects the
     * packager's `Studio` rules-config source, and can be combined with
     * `governanceProduct`.
     *
     * When there is a tenant to ask, it is asked first and this file is
     * refused only if a published policy comes back for the product. It still
     * stands when the tenant publishes none, when the question could not be
     * answered, and when there is no signed-in tenant at all.
     */
    governanceFilePath?: string;
    /**
     * Which rules-config source the packager should read the policy from.
     *
     * Not a CLI flag: `PackCommandService` derives it from the policy file's
     * own shape, because the compiler applies a policy only when told the
     * right source and otherwise discards it without a word. Left unset by a
     * caller, the service resolves it; set, it is used as given.
     */
    governanceFileType?: RulesConfigFileType;
    /**
     * Product whose governance policy is downloaded from AutomationOps for the
     * signed-in tenant (e.g. `StudioWeb`, `Development`, `Business`). Setting
     * it selects the packager's `AutomationOps` rules-config source; with
     * neither governance flag set the analyzer uses the rules shipped with the
     * WorkflowCompiler.
     *
     * Comes from `--governance-product`, or from its deprecated alias
     * `--automation-ops-profile`, which the command collapses before this
     * layer sees it.
     */
    governanceProduct?: string;
    /**
     * Deprecated alias for {@link PackCommandOptions.governanceProduct}.
     *
     * Kept because this type ships as `@uipath/solution-tool/pack`, so a
     * programmatic caller may still be setting it — a TypeScript one would
     * stop compiling and a JavaScript one would silently lose policy
     * resolution. Setting both is rejected rather than resolved.
     */
    automationOpsProfile?: string;
}
